"""Build the dependency-free concept gallery: python3 build.py."""
import json
from html import escape as e
from pathlib import Path

ROOT = Path(__file__).resolve().parent
concepts = json.loads((ROOT / 'concepts.json').read_text())
assets = json.loads((ROOT / 'assets.json').read_text())
by_id = {a['id']: a for a in assets}
dist = ROOT / 'dist'
dist.mkdir(exist_ok=True)

def asset_link(a):
    return f'<a class="pack-link" href="{a["url"]}" target="_blank" rel="noopener noreferrer"><span>{e(a["name"])}<small>{e(a["creator"])} · {e(a["tier"])}</small></span><span aria-hidden="true">↗</span></a>'

cards = []
for i, c in enumerate(concepts, 1):
    cards.append(f'''<article class="concept" id="{c['id']}" data-genre="{c['genre']}" style="--accent:{c['color']}">
      <a class="art-link" href="assets/{c['id']}.webp" target="_blank" aria-label="Open {e(c['title'])} concept art"><img src="assets/{c['id']}.webp" alt="{e(c['alt'])}" loading="lazy" width="1672" height="941"><span class="art-badge">CONCEPT ART ↗</span><span class="number">0{i}</span></a>
      <div class="card-body"><div class="card-meta"><span class="genre"><i></i>{c['genre']}</span><span>{c['camera']} / 3D</span></div>
      <h3>{c['title']}</h3><p class="tagline">{c['tagline']}</p><p class="pitch">{c['pitch']}</p>
      <div class="scope"><span>{c['scope']}</span><span>{c['difficulty']}</span><span>{len(c['assets'])} free pack{'s' if len(c['assets']) != 1 else ''}</span></div>
      <details><summary>Explore the concept <span aria-hidden="true">+</span></summary><div class="brief">
      <h4>The hook</h4><p>{c['hook']}</p><h4>The core loop</h4><ol>{''.join('<li>'+e(s)+'</li>' for s in c['loop'])}</ol>
      <h4>The first playable build</h4><p>{c['mvp']}</p><h4>What we'll make</h4><p>{c['custom']}</p><h4>What we'll learn</h4><p>{c['lesson']}</p><h4>The tricky part</h4><p>{c['risk']}</p><h4>The YouTube angle</h4><p>{c['video']}</p>
      <h4>The free asset shortlist</h4>{''.join(asset_link(by_id[x]) for x in c['assets'])}
      <a class="download" href="assets/{c['id']}.webp" download="{c['id']}-concept.webp">Download concept image ↓</a>
      </div></details></div></article>''')

rows = ''.join(f'<tr><th scope="row"><a href="#{c["id"]}">{c["title"]} ↗</a></th><td>{c["genre"]}</td><td>{c["scope"]}</td><td>{c["difficulty"]}</td><td>{c["camera"]}</td></tr>' for c in concepts)
pack_rows = ''.join(f'<tr><th scope="row"><a href="{a["url"]}" target="_blank" rel="noopener noreferrer">{a["name"]} ↗</a><small>{a["creator"]}</small></th><td>{a["use"]}</td><td><span class="license-tag">{"CC0" if a["creator"] == "Kay Lousberg" else "QAL*"}</span><small>{a["tier"]}</small></td><td>{a["formats"]}</td></tr>' for a in assets)
tabs = ''.join(f'<button class="world-tab {"active" if i == 0 else ""}" data-slide="{i}" aria-pressed="{"true" if i == 0 else "false"}"><span>0{i+1}</span>{c["title"]}</button>' for i,c in enumerate(concepts))
filters = ''.join(f'<button data-filter="{g}" aria-pressed="{"true" if g == "All concepts" else "false"}" class="filter {"active" if g == "All concepts" else ""}">{g}</button>' for g in ['All concepts','Adventure','Puzzle','Cozy','Arcade','Platformer'])

page = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#151714"><title>Five Worlds — Small games. Big possibilities.</title><meta name="description" content="Five buildable 3D game ideas, five original concept images, and eight free asset packs cleared for games and YouTube videos. Explore the next thing we could make."><meta property="og:title" content="Five Worlds — 3D Game Concept Lab"><meta property="og:description" content="Five little worlds worth building. Explore original concept art, prototype plans, and free asset packs."><meta property="og:image" content="https://five-worlds-game-lab.letta-corporation.chatgpt.site/assets/last-light.webp"><meta property="og:type" content="website"><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="style.css"><script src="app.js" defer></script></head><body>
<a class="skip" href="#concepts">Skip to concepts</a><div class="container">
<header><a class="brand" href="#top" aria-label="Five Worlds home"><span class="brand-mark" aria-hidden="true">✳</span>FIVE WORLDS<span class="brand-note">/ CONCEPT LAB</span></a><nav aria-label="Main navigation"><a href="#concepts">The concepts</a><a href="#assets">Free assets</a><a class="nav-cta" href="#compare">Find your next game <span aria-hidden="true">↗</span></a></nav></header>
<main id="top"><section class="intro" aria-labelledby="headline"><div><p class="eyebrow"><span class="status-dot"></span> A COLLECTION OF THINGS WE COULD MAKE</p><h1 id="headline">Small games.<br><em>Big possibilities.</em></h1></div><div class="intro-note"><span class="spark" aria-hidden="true">✧</span><p>Five original 3D worlds.<br>Real ideas. Free assets.<br>A starting point for our next game.</p><a class="text-link" href="#concepts">Pick a world to build <span aria-hidden="true">↓</span></a></div></section>
<section class="spotlight" aria-label="Featured concepts"><div class="hero-art"><img id="hero-image" src="assets/last-light.webp" alt="{concepts[0]['alt']}" width="1672" height="941" fetchpriority="high"><div class="hero-shade"></div><span class="hero-label">THE NEXT ADVENTURE STARTS SMALL</span><div class="hero-caption"><div><p id="hero-genre">01 / ADVENTURE</p><h2 id="hero-title">Last Light Courier</h2><p id="hero-tagline">A little light. A long way home.</p></div><a id="hero-link" class="round-link" href="#last-light" aria-label="Explore Last Light Courier">↗</a></div><div class="hero-controls"><button id="prev" aria-label="Previous concept">←</button><span id="slide-count" aria-live="polite">01 / 05</span><button id="next" aria-label="Next concept">→</button></div></div><div class="world-tabs" aria-label="Choose a featured concept">{tabs}</div></section>
<div class="facts"><span><b>05</b> original concepts</span><span><b>05</b> original images</span><span><b>08</b> free asset packs</span><span class="youtube"><i></i> Ready for your YouTube devlog</span></div>
<section id="concepts" class="section" aria-labelledby="concept-heading"><div class="section-head"><div><p class="eyebrow">01 / THE POSSIBILITIES</p><h2 id="concept-heading">Which world calls to you?</h2></div><p>Small enough to start.<br>Interesting enough to finish.</p></div><div class="filter-bar" aria-label="Filter concepts by genre">{filters}<span class="result-count" aria-live="polite">5 concepts</span></div><div class="concept-grid">{''.join(cards)}</div><p class="art-note">ART DIRECTION, NOT GAMEPLAY FOOTAGE — These five AI-generated images are original visual targets. The linked packs provide a starting point; custom models, lighting, effects, and code are still needed.</p></section>
<section id="compare" class="section compare" aria-labelledby="compare-heading"><div class="section-head"><div><p class="eyebrow">02 / PICK A STARTING POINT</p><h2 id="compare-heading">A good idea fits the scope.</h2></div><p>All five are single-player prototypes.<br>These are scope judgments, not delivery estimates.</p></div><div class="table-wrap"><table><caption class="sr-only">Compare the five game concepts</caption><thead><tr><th scope="col">The concept</th><th scope="col">Genre</th><th scope="col">First playable</th><th scope="col">Build complexity</th><th scope="col">Camera</th></tr></thead><tbody>{rows}</tbody></table></div><div class="recommendation"><span class="rec-icon" aria-hidden="true">↳</span><p><b>Our first-build pick: Midnight Groundskeeper.</b> One enclosed scene and a few satisfying interactions give us a complete little game with a strong before-and-after moment.</p><a href="#midnight-garden">See the brief ↗</a></div></section>
<section id="assets" class="section" aria-labelledby="assets-heading"><div class="section-head"><div><p class="eyebrow">03 / THE BUILDING BLOCKS</p><h2 id="assets-heading">Good worlds start with good assets.</h2></div><p>Eight free packs. Two independent creators.<br>No Kenney assets. Sources checked 17 October 2026.</p></div><div class="asset-intro"><p>Every pack below has a free download option and permits commercial projects. Follow the creator link for the pack; choose the <b>FREE</b> tier on KayKit's name-your-price pages. Paid extras and source editions are optional and are excluded from these plans.</p><a class="text-link" href="#license-notes">Read the YouTube use notes ↓</a></div><div class="table-wrap"><table class="asset-table"><caption class="sr-only">Free asset packs, creators, licenses, and formats</caption><thead><tr><th scope="col">Pack / creator</th><th scope="col">What we'll use it for</th><th scope="col">Free download / license</th><th scope="col">Formats</th></tr></thead><tbody>{pack_rows}</tbody></table></div>
<div id="license-notes" class="license-notes"><div class="license-heading"><span class="play-icon" aria-hidden="true">▶</span><p class="eyebrow">YES, YOU CAN SHOW THE GAME IN A VIDEO</p><h3>Made to build.<br>Allowed to share on screen.</h3></div><div class="license-copy"><h4>Gameplay, tutorials, and monetized YouTube videos</h4><p>KayKit's free tiers are CC0. That dedication permits copying, modification, and commercial use. Quaternius's current QAL explicitly covers films, videos, renders, and games, including commercial use. These permissions cover showing the assets in your game or development video. Neither requires attribution; crediting the artists is still a nice way to support them.</p><p><a href="https://creativecommons.org/publicdomain/zero/1.0/" target="_blank" rel="noopener noreferrer">Read CC0 ↗</a> <a href="https://quaternius.com/license.html" target="_blank" rel="noopener noreferrer">Read Quaternius's QAL ↗</a></p><h4>* A detail about Quaternius's license</h4><p>The selected older pack pages still display CC0 badges. The creator's current license page is QAL v1.0, updated 28 August 2026. We show both signals rather than assuming all new downloads are CC0. Follow the license shipped with your download and retain a copy. QAL permits finished games and videos, but prohibits redistribution of the models as standalone assets, packs, or templates and false claims of authorship. For a public tutorial repository, link to the original downloads instead of bundling QAL assets.</p><p class="small-note">This gallery includes our concept art and links to the packs, not redistributed third-party models. Music and sound effects are not included in this asset shortlist.</p><button class="copy-button" id="copy-credits">Copy optional YouTube credits <span aria-hidden="true">↗</span></button><p id="copy-status" role="status"></p></div></div></section>
<section class="closing"><p class="eyebrow">FROM “WHAT IF” TO FIRST PLAYABLE</p><h2>Pick one.<br><em>Let's make it real.</em></h2><a class="pill-link" href="#concepts">Back to the five worlds ↑</a></section></main>
<footer><a class="brand" href="#top"><span class="brand-mark" aria-hidden="true">✳</span>FIVE WORLDS</a><p>Original ideas & concept art · October 2026</p><a href="https://github.com/MarcoPaoletta/five-worlds-game-lab" target="_blank" rel="noopener noreferrer">View source on GitHub ↗</a></footer></div><script id="concept-data" type="application/json">{json.dumps(concepts).replace('<', chr(92)+'u003c')}</script></body></html>'''
(dist / 'index.html').write_text(page)
(dist / 'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="#d5f39d"/><text x="32" y="47" text-anchor="middle" font-size="49" fill="#151714">✳</text></svg>')
print(f'Built {len(concepts)} concepts and {len(assets)} asset references.')
